import{R as t,e as r,f as s,U as o}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Address Finder","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/address-providers/addressfinder.md","filePath":"integrations/address-providers/addressfinder.md","lastUpdated":1775908585000}'),n={name:"integrations/address-providers/addressfinder.md"};function d(a,e,i,l,h,c){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="address-finder" tabindex="-1">Address Finder <a class="header-anchor" href="#address-finder" aria-label="Permalink to &quot;Address Finder&quot;">​</a></h1><p>Use <a href="https://addressfinder.com.au/" target="_blank" rel="noreferrer">Address Finder</a> to use their service to suggest addresses. Address Finder is specifically for Australian and New Zealand addresses, and handles their addresses better than other options.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Address Providers</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Address Finder as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-address-finder-api" tabindex="-1">Step 2. Connect to the Address Finder API <a class="header-anchor" href="#step-2-connect-to-the-address-finder-api" aria-label="Permalink to &quot;Step 2. Connect to the Address Finder API&quot;">​</a></h3><ol><li>Login to your <a href="https://portal.addressfinder.net/sessions/login" target="_blank">AddressFinder</a> account.</li><li>Click the account dropdown in the top-right corner of the screen, and select <strong>Settings</strong>.</li><li>Under the <strong>Account</strong> section, copy the key into the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-field-setting" tabindex="-1">Step 3. Field Setting <a class="header-anchor" href="#step-3-field-setting" aria-label="Permalink to &quot;Step 3. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add an <strong>Address</strong> field to your form.</li><li>Enable the <strong>Auto-Complete</strong> sub-field option.</li><li>Select Address Finder for the <strong>Auto-Complete Integration</strong>.</li></ol><p>You can also provide <a href="https://addressfinder.com.au/docs/widget_docs" target="_blank" rel="noreferrer">Widget Options</a> in the table field. The <code>value</code> content must be valid JSON, so ensure you encase strings in <code>&quot;</code> characters. For example, the below might return the location (street, suburb and city) results.</p><table tabindex="0"><thead><tr><th>Option</th><th>Value</th></tr></thead><tbody><tr><td><code>show_locations</code></td><td><code>true</code></td></tr></tbody></table>',10)])])}const f=t(n,[["render",d]]);export{p as __pageData,f as default};
